#!/usr/bin/env node
/**
 * Generates a C translation unit containing a 32 KiB dense blob in its own section.
 *
 * Why a generator instead of a checked-in .c file: 32 KiB of hex literals is ~2000 lines
 * of noise that no reviewer will ever read. The generator is the source of truth, it is
 * deterministic, and it self-checks the property the fixture exists to exercise.
 *
 *   node gen_packed.mjs [output.c]     write to file, or stdout when omitted
 *
 * Self-check: the generated bytes must measure >= 7.99 bits/byte Shannon entropy. If a
 * future edit to the PRNG breaks that, this script exits non-zero rather than silently
 * producing a fixture that no longer tests anything.
 */

import fs from 'node:fs';

const SIZE = 32768;
const MIN_ENTROPY = 7.99;
const SECTION = '.blob';

function entropyOf(buf) {
  const counts = new Uint32Array(256);
  for (const b of buf) counts[b]++;
  let h = 0;
  for (const n of counts) {
    if (n) {
      const p = n / buf.length;
      h -= p * Math.log2(p);
    }
  }
  return h;
}

/** xorshift32, seeded so every build of this fixture is byte-identical. */
function buildBlob() {
  const buf = Buffer.alloc(SIZE);
  let s = 0x12345678;
  for (let i = 0; i < SIZE; i++) {
    s ^= s << 13; s >>>= 0;
    s ^= s >>> 17;
    s ^= s << 5;  s >>>= 0;
    buf[i] = s & 0xff;
  }
  return buf;
}

const blob = buildBlob();
const measured = entropyOf(blob);

if (measured < MIN_ENTROPY) {
  console.error(
    `gen_packed: generated blob entropy ${measured.toFixed(4)} is below the required ` +
    `${MIN_ENTROPY}. The fixture would no longer exercise the packing signal.`
  );
  process.exit(1);
}

const rows = [];
for (let off = 0; off < SIZE; off += 16) {
  const chunk = Array.from(blob.subarray(off, off + 16), (b) => '0x' + b.toString(16).padStart(2, '0'));
  rows.push('    ' + chunk.join(', ') + ',');
}

const source = `/*
 * GENERATED by fixtures/src/gen_packed.mjs - do not edit, do not commit.
 *
 * Fixture: a binary carrying a ${SECTION} section of ${SIZE} bytes at entropy
 * ${measured.toFixed(3)} bits/byte, which is the signal a triage is supposed to flag as
 * "compressed or encrypted payload". The rest of the binary is ordinary code.
 *
 * Ground truth (see fixtures/README.md):
 *   - section ${SECTION} exists with entropy >= 7.9
 *   - literal "REVSKILLS_MARKER_PACKED_v1" is present in .rodata
 *   - the binary is NOT actually packed: entry point is inside a normal executable
 *     section, and .text entropy stays in the 5.5-6.8 band. It is the honest
 *     false-positive control for the entropy threshold.
 */

#include <stdio.h>

const char revskills_marker_packed[] = "REVSKILLS_MARKER_PACKED_v1";

__attribute__((noinline, used, aligned(64)))
__attribute__((section("${SECTION}")))
const unsigned char revskills_blob[${SIZE}] = {
${rows.join('\n')}
};

int main(void)
{
    unsigned long acc = 0;
    for (unsigned long i = 0; i < ${SIZE}; i += 4096) {
        acc = (acc * 33) + revskills_blob[i];
    }
    printf("%s %lu\\n", revskills_marker_packed, acc % 100000);
    return 0;
}
`;

const outPath = process.argv[2];
if (outPath) {
  fs.writeFileSync(outPath, source, 'utf8');
  console.error(`gen_packed: wrote ${outPath} (${SIZE} bytes of section ${SECTION}, entropy ${measured.toFixed(3)})`);
} else {
  process.stdout.write(source);
}
